/* HHA chapters 1, 2, 8, 14 — role, reporting, rights, rules.
   Question tuple: [id, correctIndex, [termEN, termHT], [HT q, a, b, c, d, explanation], [EN ...]]. First 5 = chapter check.
   Block: [type, HT, EN]; type p = paragraph, li = bullet, n = numbered. Sources: see content/SOURCES.md */
(window.HHA = window.HHA || []).push(
{ch:1, cfr:"(b)(3)(i)", observed:true,
 title:["Wòl ou, limit travay ou ak kominikasyon","Your role, scope and communication"],
 src:["S6","S12"],
 sections:[
  {h:["Wòl ou nan ekip la","Your role on the team"],src:["S12"],b:[
   ["p","Yon enfimyè (RN) oswa yon terapis asiyen w bay yon kliyan, epi li ekri enstriksyon swen pou ou. Ou fè pati ekip entèdisiplinè a: enfimyè, terapis, travayè sosyal ak ou menm.","A registered nurse (RN) or a therapist assigns you to a client and writes care instructions for you. You are part of the interdisciplinary team: nurses, therapists, social workers and you."],
   ["li","Ou rapòte chanjman nan kondisyon kliyan an bay enfimyè a oswa terapis la.","You report changes in the client's condition to the nurse or therapist."],
   ["li","Ou ranpli dosye yo dapre règ ajans ou.","You complete records according to your agency's policies."],
   ["li","Ou ka patisipe nan reyinyon ekip la an pèsòn, pa telefòn oswa pa videyo. Sa w obsève enpòtan, paske ou pase plis tan ak kliyan an.","You may join team meetings in person, by phone or by video. What you observe matters, because you spend more time with the client."]]},
  {h:["Sa w gen dwa fè","What you may do"],src:["S12"],b:[
   ["p","Yon ed swen a domisil fè sèlman travay ki:","A home health aide only does tasks that are:"],
   ["n","Doktè a oswa yon pratisyen otorize mande.","Ordered by the doctor or an allowed practitioner."],
   ["n","Ekri nan plan swen an.","Written in the plan of care."],
   ["n","Lwa leta a pèmèt.","Allowed under state law."],
   ["n","Ou te resevwa fòmasyon pou yo.","Covered by your training."],
   ["p","Travay ou gen ladan: swen pèsonèl dirèk, ti pwosedi senp pou ede enfimyè a oswa terapis la, ede kliyan an mache oswa fè egzèsis, epi ede l ak medikaman li konn pran pou kont li.","Your duties include: hands-on personal care, simple procedures that extend nursing or therapy, help with walking or exercises, and help with medications the client normally takes on their own."]]},
  {h:["Ede ak medikaman: yon wòl pasif sèlman","Helping with medications: a passive role only"],src:["S12"],b:[
   ["p","Règ federal la di ed la ka gen sèlman yon wòl pasif. Egzanp sa w ka fè:","Federal guidance says the aide may take only a passive role. Examples of what you may do:"],
   ["li","Pote medikaman an bay kliyan an, nan bwat grenn li oswa nan veso li, si l mande w.","Bring the medication to the client, in their pill organizer or container, when they ask."],
   ["li","Ba l dlo oswa yon lòt likid pou l pran l.","Give fluids to take it with."],
   ["li","Fè l sonje lè pou l pran medikaman li.","Remind the client to take a medication."],
   ["li","Mete yon krèm san preskripsyon sou po ki pa blese, jan yo te montre w.","Apply a non-prescription cream to unbroken skin, as you were instructed."],
   ["p","Pa janm chwazi, chanje oswa bay yon dòz, ni bay piki. Si w pa sèten, rele enfimyè a.","Never choose, change or give a dose, and never give injections. If you are not sure, call the nurse."]]},
  {h:["Pale ak kliyan an ak fanmi an","Talking with the client and family"],src:["S12"],b:[
   ["p","Gid federal la di yon bon ed kenbe yon kominikasyon ouvè: li eksplike sa l pral fè, li poze kesyon ouvè, li mande opinyon kliyan an, epi li reponn a bezwen kliyan an, reprezantan l, moun k ap okipe l ak fanmi l.","Federal guidance says a good aide keeps open communication: they explain what they will do, ask open-ended questions, ask for the client's feedback, and respond to the needs of the client, their representative, caregivers and family."],
   ["li","Frape anvan w antre, prezante w, epi rele kliyan an jan l pito.","Knock before entering, introduce yourself, and call the client by the name they prefer."],
   ["li","Kesyon ouvè: «Kijan w te dòmi yè swa?» olye «Ou te dòmi?»","Open-ended question: “How did you sleep last night?” instead of “Did you sleep?”"],
   ["li","Pale klè epi anfas moun ki gen pwoblèm tande. Di moun ki pa wè byen kote bagay yo ye.","Speak clearly and face people with hearing loss. Tell people with low vision where things are."],
   ["li","Si kliyan an pa pale lang ou byen, mande ajans ou pou sèvis entèprèt. Ajans yo dwe bay enfòmasyon nan yon lang kliyan an konprann.","If the client does not speak your language well, ask your agency for interpreter services. Agencies must give information in a language the client understands."]]},
  {h:["Pale ak ekip la","Talking with the team"],src:["S6"],b:[
   ["li","Li enstriksyon swen yo anvan chak vizit. Si yon bagay pa klè, mande anvan w kòmanse.","Read the care instructions before each visit. If something is unclear, ask before you start."],
   ["li","Lè w rapòte, di kisa ou wè, ki lè, ak konbyen. Egzanp: «Tanperati 100.8°F a 10è, li di l gen frison.»","When you report, say what you saw, when, and how much. Example: “Temperature 100.8°F at 10 a.m.; she says she has chills.”"],
   ["li","Sou egzamen konpetans lan, yon enfimyè ap gade w pandan w ap kominike ak yon kliyan oswa yon moun k ap jwe wòl kliyan.","On the competency evaluation, a nurse watches you communicate with a client or a person playing the client."]]}],
 terms:[["plan of care","plan swen"],["care instructions","enstriksyon swen"],["interdisciplinary team","ekip entèdisiplinè"],["registered nurse (RN)","enfimyè (RN)"],["self-administered medication","medikaman kliyan an pran pou kont li"],["open-ended question","kesyon ouvè"],["interpreter","entèprèt"]],
 qs:[
  ["h101",1,["registered nurse (RN)","enfimyè (RN)"],
   ["Kiyès ki asiyen w bay yon kliyan epi ki ekri enstriksyon swen ou?","Fanmi kliyan an","Yon enfimyè (RN) oswa yon terapis","Lòt ed swen yo","Ou menm, apre premye vizit la","Yon RN oswa yon lòt pwofesyonèl kalifye (terapis) asiyen ed la bay yon kliyan espesifik epi ekri enstriksyon swen yo."],
   ["Who assigns you to a client and writes your care instructions?","The client's family","A registered nurse or a therapist","Other aides","You, after the first visit","An RN or another qualified professional (a therapist) assigns the aide to a specific client and writes the care instructions."]],
  ["h102",2,["self-administered medication","medikaman kliyan an pran pou kont li"],
   ["Ki èd ak medikaman yon ed swen a domisil gen dwa bay?","Chwazi dòz la si kliyan an gen doulè","Bay yon piki ensilin","Fè kliyan an sonje lè pou l pran medikaman li","Kraze grenn yo pou mete nan manje san enfimyè a pa di l","Ed la ka gen yon wòl pasif sèlman: fè kliyan an sonje, pote medikaman an, ba l dlo, oswa mete yon krèm san preskripsyon sou po ki pa blese."],
   ["Which help with medications is a home health aide allowed to give?","Choose the dose if the client is in pain","Give an insulin injection","Remind the client when to take their medication","Crush pills into food without the nurse's direction","The aide may take only a passive role: reminding, bringing the medication, giving fluids, or applying a non-prescription cream to unbroken skin."]],
  ["h103",0,["scope","limit travay"],
   ["Kliyan an mande w chanje pansman sou blesi li, men sa pa nan plan swen an. Kisa ou fè?","Pa fè l; rele enfimyè a oswa sipèvizè a anvan","Fè l paske l mande w","Mande vwazen an ede w","Fè l epi pa ekri l","Ou fè sèlman travay ki nan plan swen an epi ou te resevwa fòmasyon pou yo. Tcheke ak enfimyè a."],
   ["The client asks you to change a wound dressing, but it is not in the plan of care. What do you do?","Do not do it; call the nurse or supervisor first","Do it because the client asked","Ask a neighbor to help","Do it and leave it out of your notes","You only do tasks that are in the plan of care and covered by your training. Check with the nurse."]],
  ["h104",3,["open communication","kominikasyon ouvè"],
   ["Dapre gid federal la, kisa «kominikasyon ouvè» vle di pou yon ed?","Pale sèlman ak enfimyè a sou swen kliyan an, janm ak fanmi an","Fè travay la san pale pou pa deranje kliyan an","Ba kliyan an ak fanmi an tout enfòmasyon medikal ki nan dosye a ou menm","Eksplike sa w pral fè, poze kesyon ouvè, epi reponn a bezwen kliyan an ak fanmi l","Kominikasyon ouvè vle di eksplike, poze kesyon ouvè, mande opinyon, epi reponn a bezwen kliyan an, reprezantan l ak fanmi l."],
   ["According to federal guidance, what does “open communication” mean for an aide?","Talking only with the nurse about the client's care, never with the family","Working silently so you do not bother the client","Giving the client and family all the medical information in the chart yourself","Explaining what you will do, asking open-ended questions, and responding to the client's and family's needs","Open communication means explaining, asking open-ended questions, seeking feedback, and responding to the needs of the client, representative and family."]],
  ["h105",1,["open-ended question","kesyon ouvè"],
   ["Ki kesyon sa yo ki se yon kesyon ouvè?","Ou te manje?","Kijan ou santi w jodi a?","Ou gen doulè, wi oswa non?","Ou pare?","Yon kesyon ouvè pa ka reponn ak wi oswa non. Li ba w plis enfòmasyon sou kijan kliyan an ye."],
   ["Which of these is an open-ended question?","Did you eat?","How are you feeling today?","Are you in pain, yes or no?","Are you ready?","An open-ended question cannot be answered with yes or no. It tells you more about how the client is doing."]],
  ["h106",2,["interpreter","entèprèt"],
   ["Kliyan w lan pa pale Anglè byen epi ou pa pale lang li. Kisa ki pi bon?","Pale pi fò e pi dousman an Anglè","Fè siy ak men sèlman, san esplikasyon","Mande ajans ou pou sèvis entèprèt","Pa pale ak li ditou","Ajans yo dwe bay enfòmasyon nan yon lang kliyan an konprann. Mande sèvis entèprèt."],
   ["Your client does not speak English well and you do not speak their language. What is best?","Speak louder and more slowly in English","Use gestures only and skip the explanations","Ask your agency for interpreter services","Avoid talking to them","Agencies must give information in a language the client understands. Ask for interpreter services."]],
  ["hha1",0,["care plan","plan swen"],
   ["Kisa ki di yon ed swen a domisil ki travay pou l fè pou yon kliyan?","Plan swen enfimyè oswa sipèvizè a ekri","Sa fanmi an mande jou sa a","Sa ed la panse ki pi bon","Vwazen kliyan an","Swiv plan swen ki ekri a. Si yon moun mande w yon travay ki pa ladan l, verifye ak sipèvizè w anvan."],
   ["What tells a home health aide which tasks to do for a client?","The care plan from the nurse or supervisor","Whatever the family asks for that day","What the aide thinks is best","The client's neighbors","Follow the written care plan. If someone asks for a task that is not on it, check with your supervisor first."]],
  ["hha7",1,["dose","dòz"],
   ["Kliyan w lan mande w ba l plis grenn pou doulè l. Kisa ou fè?","Ba l pi gwo dòz la si l di l gen doulè","Pa chanje dòz la; rapòte sa bay enfimyè a","Ba l mwatye sa l mande a anplis","Mande yon moun nan fanmi an pou l deside dòz la","Pa janm chanje yon medikaman oswa yon dòz. Rapòte doulè a ak demann lan bay enfimyè oswa sipèvizè a."],
   ["Your client asks you for a bigger dose of their pain pill. What do you do?","Give the bigger dose if they say they are in pain","Do not change the dose; report it to the nurse","Give half of the extra amount","Ask a family member to decide on the dose","Never change a medication or dose. Report the pain and the request to the nurse or supervisor."]],
  ["h107", 3, ["injection", "piki"], ["Kliyan w lan mande w ba l piki ensilin li paske men l ap tranble. Kisa ou fè?", "Ba l li, paske kliyan an mande w", "Ba l li si yon moun nan fanmi an ap gade", "Ba l mwatye dòz la pou pi an sekirite", "Pa ba l li; rele enfimyè a", "Ed swen pa janm bay piki ni dòz. Wòl ou ak medikaman se yon wòl pasif sèlman. Rele enfimyè a."], ["Your client asks you to give their insulin shot because their hands are shaking. What do you do?", "Give it, since the client asked", "Give it if a family member watches", "Give half the dose to be safe", "Do not give it; call the nurse", "Aides never give injections or doses. Your role with medications is passive only. Call the nurse."]],
  ["h108", 1, ["introduce yourself", "prezante w"], ["Ou rive pou premye vizit ak yon nouvo kliyan. Kisa pou w fè an premye?", "Kòmanse swen an touswit pou w gen tan fè tout travay yo", "Frape, prezante w, epi mande l ki jan li pito yo rele l", "Rele l pa ti non l touswit pou w sanble zanmi", "Mande fanmi an eksplike kiyès ou ye", "Frape anvan w antre, prezante w, epi rele kliyan an jan l pito. Sa montre respè epi li bati konfyans."], ["You arrive for a first visit with a new client. What should you do first?", "Start care right away so you have time for every task", "Knock, introduce yourself, and ask what name they prefer", "Use their first name right away to sound friendly", "Ask the family to explain who you are", "Knock before entering, introduce yourself, and call the client by the name they prefer. This shows respect and builds trust."]],
  ["h109", 2, ["hearing loss", "pwoblèm tande"], ["Kliyan w lan gen pwoblèm tande. Kijan pou w pale avè l?", "Rele fò pou l tande w", "Pale depi lòt chanm nan", "Kanpe anfas li epi pale klè", "Pale sèlman ak fanmi an", "Kanpe anfas moun nan pou l wè figi w, epi pale klè. Lè w rele, mo yo vin pi difisil pou konprann."], ["Your client has hearing loss. How should you speak with them?", "Shout so they can hear you", "Speak from the next room", "Face them and speak clearly", "Talk only to the family", "Face the person so they can see your face, and speak clearly. Shouting makes words harder to understand."]],
  ["h110", 0, ["low vision", "pa wè byen"], ["Kliyan w lan pa wè byen. Ou mete plato manje midi a devan l. Kisa ki ede plis?", "Di l kote chak manje ak bwason ye sou plato a", "Ba l manje nan bouch pou l pa jete", "Deplase afè l yo pou chanm nan rete pwòp", "Pa di anyen pou l pa wont", "Di moun ki pa wè byen kote bagay yo ye. Konsa li ka manje poukont li, san danje."], ["Your client has low vision. You set their lunch tray in front of them. What helps most?", "Tell them where each food and drink is on the tray", "Feed them so they do not spill", "Move their things around to keep the room neat", "Say nothing so they are not embarrassed", "Tell a person with low vision where things are. Then they can eat on their own, safely."]],
  ["h111", 2, ["care instructions", "enstriksyon swen"], ["Anvan yon vizit, ou li enstriksyon swen yo epi yon travay pa klè pou ou. Kisa ou fè?", "Sote travay sa a jodi a", "Fè l jan w te fè l pou yon lòt kliyan", "Mande enfimyè a oswa sipèvizè w anvan w kòmanse", "Mande kliyan an kijan pou w fè l", "Li enstriksyon swen yo anvan chak vizit. Si yon bagay pa klè, mande anvan w kòmanse, pa apre."], ["Before a visit, you read the care instructions and one task is not clear to you. What do you do?", "Skip that task today", "Do it the way you did for another client", "Ask the nurse or supervisor before you start", "Ask the client how to do it", "Read the care instructions before each visit. If something is unclear, ask before you start, not after."]]]
},
{ch:2, cfr:"(b)(3)(ii)",
 title:["Obsève, rapòte ak ekri","Observing, reporting and documenting"],
 src:["S6","S12","S1"],
 sections:[
  {h:["Obsève ak sans ou","Observe with your senses"],src:["S1"],b:[
   ["p","Ou se je ak zòrèy ekip la lakay kliyan an. Sèvi ak tout sans ou: sa w wè, sa w tande, sa w santi (sant), ak sa w touche.","You are the team's eyes and ears in the client's home. Use all your senses: what you see, hear, smell and touch."],
   ["li","Konnen sa ki nòmal pou kliyan sa a. Li plan swen an ak nòt vizit anvan yo.","Know what is normal for this client. Read the care plan and earlier visit notes."],
   ["li","Obsèvasyon objektif: sa w ka wè oswa mezire. Egzanp: «Cheviy goch anfle.»","Objective observation: what you can see or measure. Example: “Left ankle is swollen.”"],
   ["li","Obsèvasyon subjektif: sa kliyan an di w li santi. Ekri l ak pwòp mo l, ant gimè. Egzanp: kliyan an di: «Tèt mwen vire.»","Subjective observation: what the client tells you they feel. Write it in their own words, in quotes. Example: client says, “I feel dizzy.”"]]},
  {h:["Kilè pou w rapòte","When to report"],src:["S12","S6"],b:[
   ["p","Ed swen yo oblije rapòte chanjman nan kondisyon kliyan an bay enfimyè a oswa terapis la.","Aides must report changes in the client's condition to the nurse or therapist."],
   ["li","Touswit: doulè nan pwatrin, souf kout, yon tonbe, konfizyon toudenkou, san k ap koule, siy abi, oswa nenpòt bagay ki fè w pè pou sekirite kliyan an. Rele 911 pou yon ijans ki menase lavi.","Right away: chest pain, shortness of breath, a fall, sudden confusion, bleeding, signs of abuse, or anything that makes you worried about the client's safety. Call 911 for a life-threatening emergency."],
   ["li","Nan fen vizit la oswa dapre règ ajans ou: ti chanjman tankou mwens apeti, yon ti wouj sou po a, oswa dòmi mal.","At the end of the visit or by agency policy: smaller changes such as less appetite, a small red area on the skin, or poor sleep."],
   ["li","Lè w ap rapòte, bay fè yo: kisa, ki lè, konbyen, ak sa kliyan an di.","When you report, give the facts: what, when, how much, and what the client said."]]},
  {h:["Ekri nòt ou","Writing your notes"],src:["S12","S1"],b:[
   ["li","Ekri sa w fè apre w fin fè l, pa janm anvan.","Document care after you give it, never before."],
   ["li","Ekri fè, chif ak lè, pa opinyon. «Manje 50% manje midi» pi bon pase «li pa t grangou».","Write facts, numbers and times, not opinions. “Ate 50% of lunch” is better than “she wasn't hungry.”"],
   ["li","Ekri sèlman sa ou menm ou fè oswa ou wè.","Write only what you yourself did or saw."],
   ["li","Si w fè yon erè, swiv règ ajans ou pou korije l. Pa janm efase oswa itilize likid blan.","If you make a mistake, follow your agency's policy to correct it. Never erase or use correction fluid."],
   ["li","Dosye a se yon dokiman legal. Ranpli l dapre règ ajans lan chak fwa.","The record is a legal document. Complete it according to agency policy every time."]]},
  {h:["Konfidansyalite","Confidentiality"],src:["S1","S27"],b:[
   ["p","Enfòmasyon sante kliyan an prive. Pataje l sèlman ak ekip swen ki bezwen l. Pa pale sou kliyan yo ak zanmi, vwazen oswa sou rezo sosyal.","The client's health information is private. Share it only with the care team members who need it. Do not talk about clients with friends, neighbors or on social media."],
   ["li","Pa pran ni poste foto lakay kliyan an san règ ajans ou pèmèt li. Menm yon foto bèt oswa yon chanm ka montre ki moun kliyan an ye, kote l rete, oswa ekipman medikal li.","Do not take or post photos in a client's home unless your agency's policy allows it. Even a photo of a pet or a room can reveal who the client is, where they live, or their medical equipment."]]}],
 terms:[["objective","objektif"],["subjective","subjektif"],["report","rapòte"],["document","ekri nan dosye"],["clinical record","dosye klinik"],["confidential","konfidansyèl"]],
 qs:[
  ["h201",0,["objective observation","obsèvasyon objektif"],
   ["Kiyès nan obsèvasyon sa yo ki objektif?","Cheviy goch kliyan an anfle epi wouj","Kliyan an di l santi l toudi","Mwen panse li santi l poukont li","Li sanble parese","Yon obsèvasyon objektif se sa w ka wè oswa mezire. Sa kliyan an di se subjektif; opinyon pa obsèvasyon."],
   ["Which of these is an objective observation?","The client's left ankle is swollen and red","The client says she feels dizzy","I think he is lonely","She seems lazy","An objective observation is something you can see or measure. What the client says is subjective; opinions are not observations."]],
  ["h202",1,["chest pain","doulè nan pwatrin"],
   ["Kliyan an di: «Pwatrin mwen fè m mal.» Ki lè pou w rapòte sa?","Nan fen semèn nan, nan nòt chak semèn ou","Touswit; rele 911 si se yon ijans","Nan pwochen vizit ou","Sèlman si l di l ankò pita pandan vizit la","Doulè nan pwatrin ka yon ijans. Rapòte touswit epi rele 911 si siy yo grav."],
   ["The client says, “My chest hurts.” When should you report it?","At the end of the week, in your weekly notes","Right away; call 911 if it is an emergency","At your next visit","Only if they say it again later in the visit","Chest pain can be an emergency. Report it right away and call 911 if the signs are serious."]],
  ["h203",2,["document","ekri nan dosye"],
   ["Ki lè pou w ekri swen ou bay nan dosye a?","Anvan w rive kay la","Nan fen semèn nan","Apre w fin bay swen an","Sèlman si gen yon pwoblèm","Ekri swen an apre w fin fè l. Pa janm ekri yon bagay ou poko fè."],
   ["When should you document the care you gave?","Before you arrive at the home","At the end of the week","After you give the care","Only if there is a problem","Document care after you give it. Never record something you have not done yet."]],
  ["h204",3,["correction","koreksyon"],
   ["Ou fè yon erè nan nòt ou. Kisa ou fè?","Efase l","Kouvri l ak likid blan","Chire paj la","Swiv règ ajans ou pou korije l","Dosye a se yon dokiman legal. Swiv règ ajans lan pou koreksyon; pa janm efase ni kache sa w te ekri."],
   ["You make a mistake in your note. What do you do?","Erase it","Cover it with correction fluid","Tear out the page","Follow your agency's policy to correct it","The record is a legal document. Follow agency policy for corrections; never erase or hide what you wrote."]],
  ["h205",1,["subjective","subjektif"],
   ["Kliyan an di w: «Mwen pa ka respire byen lannwit.» Kijan pou w ekri sa?","Kliyan an gen opresyon","Kliyan an di: «Mwen pa ka respire byen lannwit.»","Kliyan an konn twò pè","Pa ekri l paske se sèlman sa l di","Ekri sa kliyan an di ak pwòp mo l, ant gimè. Pa fè dyagnostik."],
   ["The client tells you, “I can't breathe well at night.” How should you record it?","Client has asthma","Client says, “I can't breathe well at night.”","Client is too anxious","Do not record it because it is only what they said","Write what the client says in their own words, in quotes. Do not diagnose."]],
  ["h206",2,["confidentiality","konfidansyalite"],
   ["Yon zanmi w mande w kisa kliyan w lan genyen. Kisa ou di?","Di l si l pa pale sou sa ak lòt moun","Di l sèlman non maladi a","Pa pataje enfòmasyon sante kliyan an","Montre l foto dosye a","Enfòmasyon sante kliyan an konfidansyèl. Pataje l sèlman ak ekip swen ki bezwen l."],
   ["A friend asks you what illness your client has. What do you say?","Tell them if they promise not to repeat it","Tell them only the diagnosis","Do not share the client's health information","Show them a photo of the record","The client's health information is confidential. Share it only with the care team members who need it."]],
  ["h207",0,["baseline","sa ki nòmal pou kliyan an"],
   ["Kisa ki ede w remake chanjman nan kondisyon yon kliyan?","Konnen sa ki nòmal pou li, nan plan swen an ak nòt anvan yo","Konpare l ak lòt kliyan w okipe ki gen menm laj","Mande vwazen yo","Tann fanmi an di w lè yon bagay sanble diferan","Ou ka remake yon chanjman sèlman si w konnen sa ki nòmal pou kliyan sa a."],
   ["What helps you notice changes in a client's condition?","Knowing what is normal for them, from the care plan and earlier notes","Comparing them with other clients you care for who are the same age","Asking the neighbors","Waiting for the family to tell you when something seems different","You can only spot a change if you know what is normal for this client."]],
  ["hha9",3,["observation","obsèvasyon"],
   ["Ki pi bon nòt pou w ekri nan rapò vizit ou?","Kliyan an te move","Kliyan an te sanble parese e li pa t vle fè anyen jodi a","Mwen panse kliyan an deprime akoz fanmi an","Kliyan an manje mwatye manje midi l epi l mache 10 minit ak yon walker","Ekri fè ou wè epi ou mezire, pa opinyon. Nòt klè ede enfimyè a remake chanjman."],
   ["Which is the best note to write in your visit record?","Client was in a bad mood","Client seemed lazy and did not want to do much today","I think the client is depressed because of the family","Client ate half of lunch and walked 10 minutes with a walker","Write facts you saw and measured, not opinions. Clear notes help the nurse notice changes."]],
  ["h208", 1, ["social media", "rezo sosyal"], ["Ou vle poste yon foto ou pran lakay kliyan an sou rezo sosyal ou. Kisa ki kòrèk?", "Pa gen pwoblèm toutotan figi kliyan an pa parèt nan foto a", "Pa poste l: li ka devwale kliyan an, kay li oswa detay prive", "Pa gen pwoblèm si w pa ekri non ni adrès kliyan an okenn kote", "Pa gen pwoblèm si foto a montre sèlman bèt kliyan an oswa yon chanm", "Menm yon foto bèt oswa yon chanm ka montre ki moun kliyan an ye, kote l rete oswa enfòmasyon sante l. Pa pran ni poste foto lakay kliyan san règ ajans ou pèmèt li."], ["You want to post a photo you took in a client's home on your social media. What is correct?", "It is fine as long as the client's face is not shown in the photo", "Do not post it: it can reveal the client, their home or private details", "It is fine if you do not write the client's name or address anywhere", "It is fine if the photo only shows the client's pet or a room", "Even a photo of a pet or a room can reveal who the client is, where they live or health information. Do not take or post photos in a client's home unless your agency's policy allows it."]],
  ["h209", 1, ["change in condition", "chanjman nan kondisyon"], ["Kliyan w lan manje mwens pase dabitid jodi a, men sinon li santi l byen. Kilè pou w rapòte sa?", "Rele 911 touswit, paske manje mwens se yon ijans", "Nan fen vizit la oswa dapre règ ajans ou", "Pa janm; sa pa enpòtan", "Sèlman si sa dire yon mwa antye san l pa amelyore", "Ti chanjman, tankou mwens apeti, rapòte nan fen vizit la oswa dapre règ ajans lan. Ijans tankou doulè nan pwatrin, rapòte touswit."], ["Your client ate less than usual today but otherwise feels fine. When do you report it?", "Call 911 right away, because eating less is an emergency", "At the end of the visit or as your agency's policy says", "Never; it is not important", "Only if it lasts a whole month without getting better", "Smaller changes, like less appetite, are reported at the end of the visit or by agency policy. Emergencies like chest pain are reported right away."]],
  ["h210", 3, ["document", "ekri nan dosye"], ["Yon lòt ed mande w ekri nan dosye a ke li te benyen kliyan an, paske li te bliye. Kisa ou fè?", "Ekri l, paske li di l te fè l e dosye a dwe konplè", "Ekri l epi siyen non li", "Ekri l pita nan semèn nan, lè w fin mande kliyan an", "Pa ekri l; ekri sèlman sa ou menm ou fè oswa ou wè", "Ekri sèlman sa ou menm ou fè oswa ou wè. Dosye a se yon dokiman legal."], ["Another aide asks you to write in the record that she gave the client a bath, because she forgot. What do you do?", "Write it, since she says she did it and the record should be complete", "Write it and sign her name", "Write it later in the week, once you have asked the client", "Do not write it; write only what you yourself did or saw", "Write only what you yourself did or saw. The record is a legal document."]]]
},
{ch:8, cfr:"(b)(3)(viii)",
 title:["Bezwen kliyan an, dwa l ak pwoteksyon kont abi","Client needs, rights and protection from abuse"],
 src:["S6","S12","S1"],
 sections:[
  {h:["Respè pou moun nan ak byen l","Respect for the person and their property"],src:["S12"],b:[
   ["p","Kliyan an gen dwa pou yo trete l ak respè, li menm ak byen l. Pandan vizit ou, pa kase, pa deplase, pa pran anyen ki pou li, anndan kou deyò kay la.","The client has the right to have their person and property treated with respect. During your visits, do not damage, misplace or take anything that belongs to them, inside or outside the home."],
   ["li","Kliyan an se yon patnè nan swen l. Respekte preferans li, tankou lè vizit yo, dapre plan swen an.","The client is a partner in their care. Respect their preferences, such as visit times, within the plan of care."],
   ["li","Si w pral an reta oswa orè a chanje, avèti ajans ou pou yo ka avèti kliyan an.","If you will be late or the schedule changes, tell your agency so the client is informed."],
   ["li","Respekte kilti, relijyon ak fason kliyan an renmen fè bagay yo.","Respect the client's culture, religion and the way they like things done."]]},
  {h:["Bezwen fizik, emosyonèl ak devlopman","Physical, emotional and developmental needs"],src:["S6","S1"],b:[
   ["li","Bezwen fizik: manje, dlo, pwòpte, repo, sekirite, soulajman doulè.","Physical needs: food, fluids, hygiene, rest, safety, pain relief."],
   ["li","Bezwen emosyonèl: respè, konpayi, santi l itil, kontwole pwòp lavi l.","Emotional needs: respect, company, feeling useful, control over their own life."],
   ["li","Ankouraje kliyan an fè sa l kapab pou kont li. Sa kenbe fòs li ak diyite l.","Encourage the client to do what they can for themselves. It keeps their strength and dignity."],
   ["li","Moun ki gen demans: pale dousman, bay yon sèl enstriksyon alafwa, pa diskite, epi reponn ak kalm menm si l poze menm kesyon an plizyè fwa.","People with dementia: speak calmly, give one instruction at a time, do not argue, and answer calmly even if they ask the same question many times."],
   ["li","Si yon moun ki gen demans fache oswa akize w (pa egzanp, di ou vòlè yon bagay): rete kalm, rekonèt santiman l, ofri ede l chèche, epi chanje sijè a dousman. Pa diskite. Rapòte akizasyon an bay sipèvizè w.","If a person with dementia becomes upset or accuses you (for example, says you stole something): stay calm, acknowledge the feeling, offer to help look, and gently redirect. Do not argue. Report the accusation to your supervisor."]]},
  {h:["Vi prive pandan swen","Privacy during care"],src:["S1"],b:[
   ["li","Frape anvan w antre epi tann repons.","Knock before entering and wait for an answer."],
   ["li","Fèmen pòt ak rido pandan swen pèsonèl.","Close doors and curtains during personal care."],
   ["li","Dekouvri sèlman pati kò w ap lave a. Kenbe rès kò a kouvri.","Uncover only the part of the body you are washing. Keep the rest covered."]]},
  {h:["Abi, neglijans ak vòl","Abuse, neglect and theft"],src:["S12"],b:[
   ["p","Kliyan an gen dwa pou l pa sibi abi, ni nan men anplwaye ni nan men lòt moun lakay li. Men definisyon federal yo:","The client has the right to be free from abuse, by staff or by anyone else in their home. These are the federal definitions:"],
   ["li","Abi vèbal: pawòl, ekri oswa jès ki ensilte oswa ki imilye kliyan an.","Verbal abuse: insulting or demeaning words, writing or gestures toward the client."],
   ["li","Abi mantal: imilyasyon, arasman, menas pinisyon oswa privasyon, entimidasyon (egzanp: viv ak laperèz lakay li).","Mental abuse: humiliation, harassment, threats of punishment or deprivation, intimidation (for example, living in fear at home)."],
   ["li","Abi seksyèl: fòse, manipile oswa presyon pou nenpòt aktivite seksyèl kliyan an pa dakò, oswa li pa ka dakò.","Sexual abuse: forcing, manipulating or pressuring the client into any sexual activity they did not agree to, or cannot agree to."],
   ["li","Abi fizik: nenpòt aksyon pou fè mal, tankou frape, souflete, pense.","Physical abuse: any action meant to cause harm or pain, such as hitting, slapping or pinching."],
   ["li","Blesi orijin enkoni: yon blesi pesonn pa t wè k ap fèt, epi kliyan an pa ka eksplike.","Injury of unknown source: an injury nobody saw happen that the client cannot explain."],
   ["li","Neglijans: pa bay bagay oswa sèvis kliyan an bezwen pou l evite domaj fizik oswa soufrans mantal.","Neglect: failing to provide goods or services the client needs to avoid physical harm or mental suffering."],
   ["li","Vòl byen (misappropriation): pran oswa vòlè bagay lakay kliyan an.","Misappropriation of property: taking or stealing items from the client's home."]]},
  {h:["Rapòte touswit","Report immediately"],src:["S12"],b:[
   ["p","Nenpòt anplwaye ki remake abi, neglijans, blesi orijin enkoni oswa vòl dwe rapòte sa touswit bay ajans lan, epi bay lòt otorite dapre lwa leta a. «Touswit» vle di san reta, osito w dekouvri l.","Any staff member who notices abuse, neglect, an injury of unknown source or theft must report it immediately to the agency, and to other authorities as state law requires. “Immediately” means without delay, as soon as you discover it."],
   ["li","Ou pa mennen ankèt. Ekri sa w wè ak sa w tande, ak lè a.","You do not investigate. Write down what you saw and heard, and when."],
   ["li","Ajans ou ap ba w nimewo pou rapò nan leta w la. Lwa leta ka mande w rapòte tou dirèkteman.","Your agency will give you the state reporting number. State law may also require you to report directly."]]},
  {h:["Dwa pou refize","The right to refuse"],src:["S1"],b:[
   ["p","Kliyan an ka refize yon swen. Mande l poukisa, eksplike, pwopoze yon lòt lè, epi respekte desizyon l. Rapòte refi a bay sipèvizè w.","The client may refuse care. Ask why, explain, offer another time, and respect the decision. Report the refusal to your supervisor."]]}],
 terms:[["patient rights","dwa pasyan"],["abuse","abi"],["neglect","neglijans"],["injury of unknown source","blesi orijin enkoni"],["misappropriation of property","vòl byen kliyan"],["dementia","demans"],["dignity","diyite"]],
 qs:[
  ["h801",1,["misappropriation of property","vòl byen kliyan"],
   ["Ou wè yon kòlèg pran lajan nan bous kliyan an. Kisa sa ye, e kisa ou fè?","Se pa zafè w; se ant kòlèg la ak kliyan an","Se vòl byen kliyan (misappropriation); rapòte l touswit bay ajans lan","Mande kòlèg la remete l, epi pa di anyen si l fè l","Tann pou wè si l fè l ankò","Pran bagay lakay kliyan an se vòl byen. Ou dwe rapòte l touswit."],
   ["You see a coworker take money from the client's purse. What is this, and what do you do?","It is not your business; it is between the coworker and the client","It is misappropriation of property; report it to the agency right away","Ask the coworker to put it back, and say nothing if they do","Wait to see if it happens again","Taking items from the client's home is misappropriation of property. You must report it immediately."]],
  ["h802",2,["immediately","touswit"],
   ["Pou rapò abi, kisa «touswit» vle di dapre gid federal la?","Nan 24 èdtan apre w fin aprann sa","Anvan fen semèn nan, nan rapò chak semèn ou","San reta, osito w dekouvri l","Lè w gen tan","«Touswit» vle di san reta, osito posib apre w dekouvri sa."],
   ["For reporting abuse, what does “immediately” mean in federal guidance?","Within 24 hours of finding out","By the end of the week, in your weekly report","Without delay, as soon as you discover it","When you have time","“Immediately” means without delay, as soon as possible after you discover it."]],
  ["h803",0,["injury of unknown source","blesi orijin enkoni"],
   ["Ou jwenn yon gwo mak blese sou bra kliyan an. Pesonn pa wè sa k te pase, epi kliyan an pa ka eksplike. Kisa sa ye?","Yon blesi orijin enkoni ou dwe rapòte","Yon bagay nòmal ak laj","Yon bagay ou pa bezwen ekri","Yon pwoblèm pou fanmi an sèlman","Yon blesi pesonn pa wè k ap fèt epi kliyan an pa ka eksplike se yon blesi orijin enkoni. Rapòte l touswit."],
   ["You find a large bruise on the client's arm. Nobody saw what happened and the client cannot explain it. What is this?","An injury of unknown source that you must report","A normal part of aging","Something you do not need to record","A problem for the family only","An injury nobody saw happen and the client cannot explain is an injury of unknown source. Report it immediately."]],
  ["h804",3,["verbal abuse","abi vèbal"],
   ["Ou tande yon manm fanmi ensilte kliyan an epi menase pou l pa ba l manje. Kisa ou fè?","Pa okipe l; se zafè fanmi, se pa pa w","Mande moun nan fanmi an pou l pale pi ba bò kote kliyan an","Tann pou wè si sa rive ankò","Rapòte l touswit; se ka abi vèbal ak mantal","Ensilt ak menas privasyon ka abi vèbal ak mantal, menm lè se fanmi. Rapòte l touswit."],
   ["You hear a family member insult the client and threaten to withhold food. What do you do?","Ignore it; it is a family matter, not yours","Ask the family member to speak more quietly near the client","Wait to see if it happens again","Report it right away; it may be verbal and mental abuse","Insults and threats of deprivation can be verbal and mental abuse, even from family. Report it immediately."]],
  ["h805",1,["privacy","vi prive"],
   ["Pandan yon beny nan kabann, kijan ou pwoteje vi prive kliyan an?","Kite pòt la louvri pou w ka tande fanmi an","Dekouvri sèlman pati w ap lave a epi kenbe rès la kouvri","Retire tout dra yo yon sèl kou pou w ka travay pi vit","Mande fanmi an rete nan chanm nan","Fèmen pòt ak rido epi dekouvri sèlman pati w ap lave a."],
   ["During a bed bath, how do you protect the client's privacy?","Leave the door open so you can hear the family","Uncover only the part you are washing and keep the rest covered","Remove all the sheets at once so you can work faster","Ask the family to stay in the room","Close doors and curtains and uncover only the part you are washing."]],
  ["h806",2,["dementia","demans"],
   ["Yon kliyan ki gen demans mande w menm kesyon an plizyè fwa. Kisa ki pi bon?","Di l li te deja mande w sa","Pa reponn","Reponn ak kalm epi senp chak fwa","Diskite avè l pou l sonje","Reponn ak kalm epi senp. Diskite ka fè l pè oswa fache."],
   ["A client with dementia asks you the same question many times. What is best?","Tell them they already asked","Do not answer","Answer calmly and simply each time","Argue so they remember","Answer calmly and simply. Arguing can upset or frighten them."]],
  ["h807",0,["independence","endepandans"],
   ["Kliyan an ka bwose cheve l pou kont li, men li pran tan. Kisa ou fè?","Kite l fè l epi ede l sèlman si l bezwen","Fè l pou li pou w ka fini pi vit","Di l pa gen tan","Sote etap sa a","Ankouraje kliyan an fè sa l kapab. Sa kenbe fòs li ak diyite l."],
   ["The client can brush their own hair but it takes time. What do you do?","Let them do it and help only if needed","Do it for them so you finish faster","Tell them there is no time","Skip this step","Encourage the client to do what they can. It keeps their strength and dignity."]],
  ["hha6", 2, ["neglect", "neglijans"], ["Dapre definisyon federal yo, kisa neglijans ye?", "Pawòl, ekri oswa jès ki ensilte oswa ki imilye kliyan an", "Pran oswa vòlè bagay lakay kliyan an", "Pa bay kliyan an byen oswa sèvis li bezwen pou l pa soufri ni blese", "Yon blesi pèsonn pa t wè k ap rive e kliyan an pa ka esplike", "Neglijans se lè yo pa bay kliyan an sa l bezwen, tankou manje, swen oswa sekirite. Lòt repons yo se abi vèbal, vòl byen ak blesi orijin enkoni. Ou rapòte nenpòt nan yo touswit."], ["Under the federal definitions, what is neglect?", "Insulting or demeaning words, writing or gestures toward the client", "Taking or stealing items from the client's home", "Failing to give goods or services the client needs to avoid harm or suffering", "An injury that nobody saw happen and that the client cannot explain", "Neglect is failing to give the client what they need, such as food, care or safety. The other answers are verbal abuse, misappropriation of property and an injury of unknown source. You report any of them immediately."]],
  ["h808", 2, ["right to refuse", "dwa pou refize"], ["Kliyan an di l fatige epi l pa vle benyen jodi a, menm si plan swen an di beny. Kisa ou fè?", "Fè benyen an kanmenm, paske plan swen an mete l pou jodi a", "Rele 911", "Respekte desizyon l, mande poukisa, pwopoze yon lòt lè, epi rapòte refi a", "Sote l epi pa di pèsonn, paske se kliyan an ki mande", "Kliyan an gen dwa refize swen. Respekte l, pwopoze yon lòt lè oswa yon lòt opsyon, ekri refi a, epi rapòte l bay sipèvizè w oswa enfimyè a."], ["The client says they are tired and do not want a bath today, even though the care plan lists one. What do you do?", "Give the bath anyway, because the care plan lists it for today", "Call 911", "Respect the decision, ask why, offer another time, and report the refusal", "Skip it and tell no one, since the client asked", "Clients have the right to refuse care. Respect it, offer another time or option, document the refusal, and report it to your supervisor or the nurse."]],
  ["h809", 0, ["validation and redirection", "valide ak chanje sijè"], ["Yon kliyan ki gen demans fache epi l di ou vòlè mont li. Ki pi bon repons lan?", "Rete kalm, rekonèt santiman l, ede l chèche mont lan, oswa chanje sijè a dousman", "Esplike fèm, e diskite si sa nesesè, pou pwouve w pa t pran l", "Menase pou w kite travay la", "Fouye tiwa ak sak li touswit devan l", "Pa diskite ak yon moun ki gen demans. Rekonèt santiman l, rete kalm, ofri èd, epi chanje atansyon l dousman. Rapòte akizasyon an bay sipèvizè w."], ["A client with dementia becomes upset and says you stole their watch. What is the best response?", "Stay calm, acknowledge their feelings, offer to help look, or gently redirect", "Explain firmly, and argue if needed, to prove you did not take it", "Threaten to leave the job", "Search their drawers and bags right away in front of them", "Do not argue with a person who has dementia. Acknowledge the feeling, stay calm, offer help, and gently redirect. Report the accusation to your supervisor."]],
  ["h810", 3, ["client property", "byen kliyan an"], ["Pandan w ap netwaye, ou jwenn yon bag anba kabann kliyan an. Kisa ou fè?", "Kenbe l, paske l te pèdi", "Mete l nan sak ou pou w remèt li semèn pwochèn", "Jete l ak pousyè a", "Remèt li bay kliyan an", "Pandan vizit ou, pa kase, pa deplase, pa pran anyen ki pou kliyan an."], ["While cleaning, you find a ring under the client's bed. What do you do?", "Keep it, since it was lost", "Put it in your bag to return next week", "Throw it out with the dust", "Give it back to the client", "During your visits, do not damage, misplace or take anything that belongs to the client."]],
  ["h811", 0, ["culture", "kilti"], ["Kliyan w lan priye anvan chak manje epi li pito yo prepare manje l yon fason espesyal pou rezon relijyon. Kisa ou fè?", "Respekte pratik li epi prepare manje a jan l pito, dapre plan swen an", "Mande l sote lapriyè a pou manje a rete cho", "Kwit jan w kwit lakay ou, paske w konnen l bon pou sante", "Mande fanmi an chanje abitid kliyan an", "Respekte kilti, relijyon ak fason kliyan an renmen fè bagay yo, dapre plan swen an."], ["Your client prays before every meal and prefers food prepared a certain way for religious reasons. What do you do?", "Respect their practice and prepare food the way they prefer, within the care plan", "Ask them to skip the prayer so the food stays warm", "Cook the way you cook at home, since you know it is healthy", "Ask the family to change the client's habits", "Respect the client's culture, religion and the way they like things done, within the plan of care."]],
  ["h812", 2, ["physical abuse", "abi fizik"], ["Dapre definisyon federal yo, kiyès nan sa yo ki abi fizik?", "Di kliyan an li pa vo anyen", "Pran lajan nan bous kliyan an", "Pense kliyan an pou l fè vit", "Pa bay kliyan an manje li bezwen", "Abi fizik se nenpòt aksyon pou fè mal, tankou frape, souflete oswa pense. Lòt repons yo se abi vèbal, vòl byen ak neglijans."], ["Under the federal definitions, which of these is physical abuse?", "Telling the client they are useless", "Taking money from the client's wallet", "Pinching the client to make them hurry", "Not giving the client food they need", "Physical abuse is any action meant to cause harm or pain, such as hitting, slapping or pinching. The other answers are verbal abuse, misappropriation of property and neglect."]],
  ["h813", 1, ["investigate", "mennen ankèt"], ["Ou sispèk yon moun nan fanmi an ap fè kliyan w lan mal. Apre w fin rapòte, kisa wòl ou ye?", "Kesyone moun nan fanmi an pou w jwenn verite a", "Ekri sa w wè ak sa w tande, ak lè a; pa mennen ankèt", "Fouye kay la pou w jwenn prèv", "Di vwazen yo pou yo veye", "Ou pa mennen ankèt. Rapòte touswit epi ekri sa w wè ak sa w tande, ak lè a."], ["You suspect a family member is hurting your client. After you report it, what is your role?", "Question the family member to find out the truth", "Write down what you saw and heard, and when; do not investigate", "Search the home for proof", "Tell the neighbors so they can watch", "You do not investigate. Report immediately and write down what you saw and heard, and when."]]]
},
{ch:14, cfr:"(b)(3)(xiv)",
 title:["Lòt travay, medikaman ak règ pou rete kalifye","Other tasks, medications and staying qualified"],
 src:["S6","S12"],
 sections:[
  {h:["Travay anplis","Extra tasks"],src:["S6","S12"],b:[
   ["p","Ajans lan ka mande w fè lòt travay sèlman si lwa leta pèmèt yo. Pou nenpòt konpetans ki pa nan lis debaz la, ajans lan dwe ba w fòmasyon anvan.","The agency may ask you to do other tasks only if state law allows them. For any skill not on the basic list, the agency must train you first."],
   ["li","Si yon règ leta pi sevè pase règ federal la, se règ ki pi sevè a ki aplike. Mande ajans ou sa leta w mande.","If a state rule is stricter than the federal rule, the stricter rule applies. Ask your agency what your state requires."]]},
  {h:["Medikaman: sa w ka fè ak sa w pa ka fè","Medications: what you can and cannot do"],src:["S12"],b:[
   ["p","«Pran medikaman pou kont li» vle di kliyan an (oswa moun k ap okipe l) jere tout bagay: kenbe medikaman yo an sekirite, pran bon dòz la, pran l a lè, epi rele famasi a.","“Self-administration” means the client (or their caregiver) manages everything: storing medications safely, taking the right dose, taking it on time, and calling the pharmacy."],
   ["li","Ou ka: pote medikaman an jan kliyan an mande, ba l dlo, fè l sonje, mete yon krèm san preskripsyon sou po ki pa blese jan yo montre w.","You may: bring the medication as the client asks, give fluids, give reminders, and apply a non-prescription cream to unbroken skin as instructed."],
   ["li","Ou pa ka: chwazi oswa chanje dòz, ranpli bwat grenn semèn nan, bay piki, oswa deside si kliyan an bezwen yon medikaman.","You may not: choose or change a dose, fill the weekly pill organizer, give injections, or decide whether the client needs a medication."],
   ["li","Rapòte si kliyan an rate dòz, refize medikaman, oswa gen yon reyaksyon.","Report if the client misses doses, refuses a medication, or has a reaction."]]},
  {h:["Evalyasyon konpetans","The competency evaluation"],src:["S6","S12"],b:[
   ["li","Yon enfimyè (RN) fè evalyasyon an. Li dwe gade w fè konpetans pratik yo ak yon kliyan oswa yon moun k ap jwe wòl kliyan.","A registered nurse runs the evaluation. They must watch you perform the hands-on skills with a client or a person playing the client."],
   ["li","Si yo bay ou «pa satisfezan» nan yon travay, ou pa ka fè l san siveyans dirèk yon RN jiskaske w resevwa fòmasyon ankò epi w reyisi yon nouvo evalyasyon.","If you are rated “unsatisfactory” on a task, you cannot do it without direct RN supervision until you are retrained and pass a new evaluation."],
   ["li","Si w gen «pa satisfezan» nan plis pase yon sèl domèn obligatwa, ou pa pase evalyasyon an.","If you are rated unsatisfactory in more than one required area, you do not pass the evaluation."]]},
  {h:["Siveyans","Supervision"],src:["S12"],b:[
   ["li","Si kliyan an resevwa swen enfimyè oswa terapi: yon RN oswa terapis evalye swen ou omwen chak 14 jou. Ou pa oblije la.","If the client gets nursing or therapy: an RN or therapist reviews your care at least every 14 days. You do not have to be present."],
   ["li","Si kliyan an pa resevwa swen sa yo: RN lan fè yon vizit an pèsòn chak 60 jou.","If the client does not get those services: the RN makes an in-person visit every 60 days."],
   ["li","Yon pwofesyonèl ap obsève w pandan w ap bay swen omwen yon fwa pa ane (oswa de fwa pa ane pou swen ki pa teknik).","A professional will watch you give care at least once a year (twice a year for non-skilled care)."],
   ["li","Si yo jwenn yon pwoblèm nan swen ou, ou dwe fè fòmasyon ankò ak yon nouvo evalyasyon pou konpetans sa a ak konpetans ki gen rapò.","If a problem is found in your care, you must be retrained and re-evaluated on that skill and related skills."]]},
  {h:["Rete kalifye","Staying qualified"],src:["S6","S12"],b:[
   ["li","Omwen 12 èdtan fòmasyon kontinyèl (in-service) chak 12 mwa. Si fòmasyon an fèt pandan w ap bay swen, kliyan an dwe konnen epi dakò.","At least 12 hours of in-service training every 12 months. If training happens during care, the client must be told and agree."],
   ["li","Si w pase 24 mwa youn dèyè lòt san w pa travay kòm ed pou lajan, ou dwe refè yon pwogram fòmasyon oswa evalyasyon.","If you go 24 months in a row without paid aide work, you must complete a training or competency program again."],
   ["li","Yon CNA ki an règ sou rejis eta a satisfè kondisyon fòmasyon an pou travay kòm ed swen a domisil.","A CNA in good standing on the state registry meets the training requirement to work as a home health aide."]]}],
 terms:[["competency evaluation","evalyasyon konpetans"],["unsatisfactory","pa satisfezan"],["in-service training","fòmasyon kontinyèl"],["supervisory visit","vizit siveyans"],["nurse aide registry","rejis ed enfimyè"],["pill organizer","bwat grenn"]],
 qs:[
  ["h1401",1,["unsatisfactory","pa satisfezan"],
   ["Ou resevwa «pa satisfezan» nan beny nan kabann pandan evalyasyon an. Kisa sa vle di?","Ou pa ka janm bay benyen nan kabann ankò, menm apre fòmasyon","Ou ka fè l sèlman anba siveyans dirèk yon RN jiskaske w refè fòmasyon epi w pase","Ou ka fè l nòmalman","Ou ka fè l si yon moun nan fanmi kliyan an sipèvize w","Yon travay ou pa satisfezan ladan l mande siveyans dirèk RN jiskaske w refè fòmasyon epi w pase yon nouvo evalyasyon."],
   ["You are rated “unsatisfactory” on the bed bath during your evaluation. What does that mean?","You can never give a bed bath again, even after retraining","You may do it only under direct RN supervision until you are retrained and pass","You may do it as usual","You may do it if a family member of the client supervises you","A task rated unsatisfactory requires direct RN supervision until you are retrained and pass a new evaluation."]],
  ["h1402",2,["in-service training","fòmasyon kontinyèl"],
   ["Konbyen èdtan fòmasyon kontinyèl (in-service) yon ed swen a domisil bezwen chak ane?","4 èdtan","8 èdtan","12 èdtan","24 èdtan","Règ federal la mande omwen 12 èdtan fòmasyon kontinyèl chak 12 mwa."],
   ["How many hours of in-service training does a home health aide need each year?","4 hours","8 hours","12 hours","24 hours","The federal rule requires at least 12 hours of in-service training every 12 months."]],
  ["h1403",0,["24-month lapse","24 mwa san travay"],
   ["Ou pa t travay kòm ed pou lajan pandan 24 mwa youn dèyè lòt. Kisa ou dwe fè anvan w retounen?","Refè yon pwogram fòmasyon oswa evalyasyon konpetans","Anyen; sètifika w toujou valab pou tout lavi","Fè 2 èdtan fòmasyon kontinyèl","Jwenn yon lèt referans nan dènye ajans ou","Apre 24 mwa youn dèyè lòt san travay peye, ou dwe refè yon pwogram anvan w bay swen ankò."],
   ["You have not worked as a paid aide for 24 months in a row. What must you do before returning?","Complete a training or competency evaluation program again","Nothing; your certificate is still valid for life","Take 2 hours of in-service training","Get a reference letter from your last agency","After 24 consecutive months without paid aide work, you must complete a program again before giving care."]],
  ["h1404",2,["topical cream","krèm pou po"],
   ["Ki travay sa yo yon ed gen dwa fè ak medikaman?","Bay yon piki ensilin si kliyan an montre w kijan","Ranpli bwat grenn semèn kliyan an ak boutèy yo","Mete yon krèm san preskripsyon sou po ki pa blese jan yo montre w","Deside si kliyan an bezwen yon grenn pou doulè","Mete yon krèm san preskripsyon sou po ki pa blese, dapre enstriksyon, se youn nan èd pasif gid federal la bay kòm egzanp."],
   ["Which of these may an aide do with medications?","Give an insulin injection if the client shows you how","Fill the client's weekly pill organizer from the bottles","Apply a non-prescription cream to unbroken skin as instructed","Decide whether the client needs a pain pill","Applying a non-prescription cream to unbroken skin, per instructions, is one of the passive tasks federal guidance lists as an example."]],
  ["h1405",1,["state law","lwa leta"],
   ["Règ leta w la sou fòmasyon ed pi sevè pase règ federal la. Ki règ ou swiv?","Règ federal la","Règ ki pi sevè a","Sa ou pito a","Okenn","Lè yon règ leta pi sevè, se li ki aplike. Lè règ federal la pi sevè, se li ki aplike."],
   ["Your state's aide training rule is stricter than the federal rule. Which do you follow?","The federal rule","The stricter rule","Whichever you prefer","Neither","When a state rule is stricter, it applies. When the federal rule is stricter, it applies."]],
  ["h1406",0,["supervisory visit","vizit siveyans"],
   ["Kliyan an resevwa swen enfimyè. Chak konbyen tan yon RN oswa terapis dwe evalye swen ou bay?","Omwen chak 14 jou","Chak 6 mwa","Yon fwa pa ane","Sèlman si fanmi an plenyen","Lè kliyan an resevwa swen teknik, evalyasyon siveyans lan fèt omwen chak 14 jou. Ed la pa oblije la."],
   ["The client receives nursing care. How often must an RN or therapist review the care you give?","At least every 14 days","Every 6 months","Once a year","Only if the family complains","When the client gets skilled services, the supervisory review happens at least every 14 days. The aide does not need to be present."]],
  ["h1407",2,["training","fòmasyon"],
   ["Ajans lan vle w fè yon nouvo travay ou pa t janm aprann. Kisa ki dwe fèt anvan?","Ou eseye l pou wè","Yon lòt ed esplike w pa telefòn","Ajans lan ba w fòmasyon pou travay sa a","Ou li sou entènèt","Ajans lan responsab pou fòme ed yo pou konpetans ki pa nan lis debaz la, anvan yo fè yo."],
   ["Your agency wants you to do a new task you were never taught. What must happen first?","You try it and see","Another aide explains it by phone","The agency trains you for that task","You read about it online","The agency is responsible for training aides on skills beyond the basic list before they perform them."]],
  ["h1408",1,["nurse aide registry","rejis ed enfimyè"],
   ["Ou se yon CNA ki an règ sou rejis eta a. Èske w satisfè kondisyon fòmasyon pou travay kòm ed swen a domisil?","Non, ou dwe refè 75 èdtan","Wi","Sèlman si w gen 5 ane eksperyans","Sèlman nan lopital","Yon ed enfimyè ki fini yon pwogram apwouve pa leta epi ki an règ sou rejis la satisfè kondisyon fòmasyon ed swen a domisil."],
   ["You are a CNA in good standing on the state registry. Do you meet the training requirement to work as a home health aide?","No, you must redo 75 hours","Yes","Only with 5 years of experience","Only in hospitals","A nurse aide who completed a state-approved program and is in good standing on the registry meets the home health aide training requirement."]],
  ["h1409", 2, ["pill organizer", "bwat grenn semèn"], ["Kliyan an mande w ranpli bwat grenn semèn li. Kisa ou fè?", "Ranpli l ak atansyon apati boutèy yo", "Ranpli l si fanmi an tcheke l apre", "Pa ranpli l; di enfimyè a", "Ranpli sèlman dòz maten yo", "Ed swen pa ka ranpli bwat grenn semèn nan, chwazi oswa chanje dòz, ni bay piki. Di enfimyè a."], ["The client asks you to fill their weekly pill organizer. What do you do?", "Fill it carefully from the bottles", "Fill it if the family checks it afterward", "Do not fill it; tell the nurse", "Fill only the morning doses", "Aides may not fill the weekly pill organizer, choose or change a dose, or give injections. Tell the nurse."]],
  ["h1410", 0, ["missed dose", "dòz rate"], ["Ou remake grenn maten kliyan an toujou nan bwat la a lè manje midi. Kisa ou fè?", "Rapòte dòz rate a bay enfimyè a", "Ba l grenn maten yo ak manje midi a", "Jete grenn yo", "Ba l doub dòz aswè a", "Rapòte si kliyan an rate dòz, refize medikaman, oswa gen yon reyaksyon. Pa janm deside oswa chanje yon dòz poukont ou."], ["At lunchtime you notice your client's morning pills are still in the organizer. What do you do?", "Report the missed dose to the nurse", "Give the morning pills with lunch", "Throw the pills away", "Give a double dose tonight", "Report if the client misses doses, refuses a medication, or has a reaction. Never decide on or change a dose yourself."]],
  ["h1411", 1, ["self-administration", "pran medikaman pou kont li"], ["Kisa sa vle di lè yon kliyan pran medikaman li pou kont li?", "Ed la retire grenn yo epi bay chak dòz", "Kliyan an oswa yon moun k ap okipe l jere estokaj, dòz, lè ak renouvèlman", "Yon enfimyè vin lakay la chak jou pou bay chak dòz", "Famasi a deside ki lè kliyan an pran chak grenn", "Pran medikaman pou kont li vle di kliyan an (oswa moun k ap okipe l) jere tout bagay: kenbe medikaman yo an sekirite, bon dòz la, a lè, epi rele famasi a."], ["What does it mean that a client self-administers their medications?", "The aide takes the pills out and gives each dose", "The client or a caregiver handles storage, doses, timing and refills", "A nurse comes to the home every day to give each dose", "The pharmacy decides when the client takes each pill", "Self-administration means the client (or their caregiver) manages everything: storing medications safely, the right dose, the right time, and calling the pharmacy."]],
  ["h1412", 3, ["competency evaluation", "evalyasyon konpetans"], ["Pandan evalyasyon konpetans ou, yo ba w «pa satisfezan» nan de domèn obligatwa. Kisa k rive?", "Ou pase, men ou dwe pratike konpetans sa yo", "Ou pase si egzamen ekri w la te bon", "Ou ka travay nan domèn sa yo ak yon kòlèg", "Ou pa pase evalyasyon an", "Si w gen «pa satisfezan» nan plis pase yon sèl domèn obligatwa, ou pa pase evalyasyon an."], ["During your competency evaluation, you are rated unsatisfactory in two required areas. What happens?", "You pass, but must practice those skills", "You pass if your written test was strong", "You can work in those areas with a coworker", "You do not pass the evaluation", "If you are rated unsatisfactory in more than one required area, you do not pass the evaluation."]],
  ["h1413", 0, ["retraining", "fòmasyon ankò"], ["Pandan yon vizit siveyans, enfimyè a jwenn yon pwoblèm nan fason w fè transfè. Kisa ki dwe rive?", "Ou fè fòmasyon ankò ak yon nouvo evalyasyon sou konpetans sa a ak konpetans ki gen rapò", "Anyen pa bezwen fèt si pèsonn pa blese", "Ou resevwa yon lèt avètisman sèlman", "Ou dwe refè tout pwogram fòmasyon 75 èdtan an", "Si yo jwenn yon pwoblèm nan swen ou, ou dwe fè fòmasyon ankò ak yon nouvo evalyasyon pou konpetans sa a ak konpetans ki gen rapò."], ["During a supervisory visit, the nurse finds a problem with how you transfer clients. What must happen?", "You are retrained and re-evaluated on that skill and related skills", "Nothing needs to happen if no one was hurt", "You get a warning letter only", "You must repeat the whole 75-hour training program", "If a problem is found in your care, you must be retrained and re-evaluated on that skill and related skills."]]]
}
);
